-- Sprint 65: expose governance audit fields for smoke recertification policy upsert.

UPDATE `admin_platform_endpoint_tools`
   SET `description` = 'Create or update a smoke recertification policy for a tenant/plugin/action/mock scope. Controls TTL, expiring-soon window, max batch size, auto enablement, and expected origin guard. Writes execution-log audit evidence with before/after summaries and changed fields.',
       `input_schema` = '{"type":"object","properties":{"policy_id":{"type":"string"},"tenant_id":{"type":"string"},"plugin_key":{"type":"string","default":"*"},"action_key":{"type":"string"},"mock_provider":{"type":"string"},"mock_resource":{"type":"string"},"certification_ttl_days":{"type":"integer","minimum":1,"maximum":365,"default":90},"expires_soon_days":{"type":"integer","minimum":1,"maximum":90,"default":14},"max_batch_size":{"type":"integer","minimum":1,"maximum":10,"default":5},"auto_recertification_enabled":{"type":"boolean","default":false},"provider_smoke_required":{"type":"boolean","default":true},"allowed_expected_origin":{"type":"string"},"status":{"type":"string","default":"active"},"priority":{"type":"integer","default":100},"notes":{"type":"string"},"metadata":{"type":"object","additionalProperties":true},"actor":{"type":"string"},"actor_id":{"type":"string"},"admin_user_id":{"type":"string"},"updated_by":{"type":"string"},"reason":{"type":"string"},"change_reason":{"type":"string"},"trace_id":{"type":"string"}},"additionalProperties":false}',
       `tags` = 'platform-plugin,smoke,recertification,policy,upsert,state_changing,no_secrets,audited,origin_guard,execution_log_audit'
 WHERE `tool_key` = 'platform_plugin_smoke_recertification_policy_upsert';
